const __defs = {};
const __cache = {};
const __env = (typeof $env !== 'undefined' && $env) ? $env : {};
const __projectDir = __env.RFP_STUDIO_DIR || '/data/rfp-studio';
function __require(name) {
  if (name.startsWith('./')) {
    const key = name.slice(2);
    if (__cache[key]) return __cache[key].exports;
    if (!__defs[key]) throw new Error('module not embedded: ' + key);
    const module = { exports: {} };
    __cache[key] = module;
    __defs[key](module, module.exports, __require, __projectDir + '/agents/lib');
