      }
      // Compliance matrix: 4 rows per slide, the platform splits it into continuation slides
      if (slideId === 's3') {
        slide.blocks = slide.blocks.map(b => (b.kind === 'table' ? { ...b, rowsPerSlide: 4 } : b));
      }
