  module.exports = {
    validateBlock,
    validateSlideSpec,
    validateDeckSpec,
    checkContentQuality,
    ALLOWED_DECK_FIELDS,
    ALLOWED_SLIDE_FIELDS,
    ALLOWED_BLOCK_KINDS,
    ALLOWED_BULLET_STYLES,
    LIMITS
  };
}

// END agents/lib/contracts.js
};

