        warnings: ['Invalid diagram source path']
      };
    }

    blocks.push({
      kind: 'image',
      src: diagram.src,
      caption: diagram.caption || i18n.translate('class_diagram_title', language)
    });
  } else {
    blocks.push({
      kind: 'note',
      text: '[TO FILL: class diagram]'
    });
  }

  const slide = {
    id: 's3c',
    type: 'content',
    title: i18n.translate('class_diagram_title', language),
