  const diagrams = [];
  const archD = makeDiagram('architecture', fr ? 'Architecture technique' : 'Technical architecture',
    renderArchitecture(archStruct, theme), generateArchitectureMermaid(archStruct), warnings);
  if (archD) diagrams.push(archD);

