  const specSlide = entry.specSlides?.find(s => s.id === mapping.id);

  return {
    specSlideId: mapping.id,
    part: mapping.part,
    of: mapping.of,
    slide: specSlide
  };
}

/**
 * Gets the responsible agent for a spec slide id
 * 
 * @param {string} specSlideId
 * @returns {string} - Agent name
 */
function getResponsibleAgent(specSlideId) {
  const agentMap = {
    's1': 'agent1',
    's2': 'agent1',
    's3': 'agent1',
    's11': 'agent1',
    's4': 'agent5',
    's6': 'agent5',
    's7': 'agent5',
    's8': 'agent5',
    's3b': 'diagrams',
    's3c': 'diagrams',
    's5': 'diagrams',
    's10': 'diagrams',
    's9': 'agent4'
  };

  return agentMap[specSlideId] || 'unknown';
}

// Export for CommonJS (n8n Code nodes) and ES modules
if (typeof module !== 'undefined' && module.exports) {
  module.exports = {
    buildProjectSlideMap,
    storeDeck,
    getDeck,
    listDecks,
    purgeOldDecks,
    mapSlideIndexToSpec,
    getResponsibleAgent,
    REGISTRY_DIR,
    setRegistryDir,
    registryDir
  };
}

// END agents/lib/registry.js
};

